def blend(a,b,t):return tuple(int(x*(1-t)+y*t) for x,y in zip(a,b))
def fit_font(text,maxwidth,maxsize=34,minsize=21):
 for size in range(maxsize,minsize-1,-1):
  f=ImageFont.truetype(font_bold,size,layout_engine=ImageFont.Layout.RAQM)
  if d.textbbox((0,0),text,font=f,direction='rtl')[2]<=maxwidth:return f
